const s=wb.getWorksheet('Cumulative');
const before=s.getRange('I2:I11').getStyle().getNumberFormat?.();
for(let r=2;r<=11;r++){ s.getRange('I'+r).setValue(`=COUNTIFS($G$14:$G$185,G${r},$J$14:$J$185,"open")`); }
const rows=[];
for(let r=2;r<=11;r++){ const c=s.getRange('I'+r); rows.push([r,s.getRange('G'+r).getValue(),c.getValue(),c.getText?.(),c.getFormula?.()].join(' | ')); }
log(before); log(rows.join('\n'));
log(await wb.evaluate('=SUM(I2:I11)'));
log(await wb.evaluate('=SUMPRODUCT((G14:G185=2018)*(LOWER(J14:J185)="open"))'));
log(await wb.evaluate('=SUMPRODUCT((G14:G185=2021)*(LOWER(J14:J185)="open"))'));
const v=wb.getRange('G14:J185').getValues();const m={};
v.forEach(x=>{if(String(x[3]).toLowerCase()==='open')m[x[0]]=(m[x[0]]||0)+1;});
log(JSON.stringify(m));
log(s.getRange('I2:I11').getStats());
wb.getRange('I1:I12')

